// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: initial deposit amount and a flag to decide whether to use attacker
    function testFuzz_property(uint256 depositAmount, bool useAttacker) public {
        // keep deposit in a reasonable non-zero range
        depositAmount = bound(depositAmount, 1, 1 ether);

        // Deploy an attacker that will re-enter on receive if requested
        Attacker attacker = new Attacker(address(c));

        // Choose who will be the depositor: either the attacker contract or an EOA
        address depositor = useAttacker ? address(attacker) : address(0xBEEF);

        // Fund depositor so they can deposit
        vm.deal(depositor, depositAmount);

        // Make depositor deposit into c
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // Verify that recorded credit is depositAmount initially via calling withdrawAll later
        // Now attempt withdrawAll from depositor; if using attacker, attacker will re-enter
        bool ok;
        if (useAttacker) {
            // Give attacker some gas funding so its reentrancy path can operate
            // The attacker will call withdrawAll which attempts to re-enter if possible
            vm.prank(depositor);
            try c.withdrawAll{value: 0}() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            vm.prank(depositor);
            try c.withdrawAll{value: 0}() {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // Single assertion: after withdrawAll completes, the contract's stored credit for the caller is zero
        // Read the credit via a helper view: since credit is private in the original contract, we can't access it directly.
        // But we can infer it by attempting a second withdrawAll: if credit is zero, the second call will be a no-op and leave contract balance unchanged.
        // So we capture contract balance before and after a second withdrawAll attempt; for the correct contract the balance should not change.

        uint256 balBefore = address(c).balance;
        vm.prank(depositor);
        try c.withdrawAll{value: 0}() {
            // success
        } catch {
            // ignore revert from second call
        }
        uint256 balAfter = address(c).balance;

        // For the reference correct contract, balBefore == balAfter for all inputs (no additional funds withdrawable after first withdrawAll)
        // The mutant with reentrancy bug can allow additional withdrawals causing balBefore != balAfter for some inputs
        assertTrue(balBefore == balAfter);
    }
}

// Attacker contract: on receiving ETH it will attempt to re-enter withdrawAll once
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _target) {
        target = _target;
        reentered = false;
    }

    receive() external payable {
        // On first receive, attempt to re-enter withdrawAll to exploit reentrancy if target withdraw calls before zeroing
        if (!reentered) {
            reentered = true;
            // try to reenter
            (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
            // ignore result
            ok;
        }
    }
}

