pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: deposit amount and an initial funding for attacker
    function testFuzz_property(uint256 depositAmount, uint256 attackerFund) public {
        // keep amounts in a reasonable wide domain but non-zero for deposit
        depositAmount = bound(depositAmount, 1, 1 ether);
        attackerFund = bound(attackerFund, depositAmount, 2 ether);

        // deploy an attacker that will re-enter c during withdraw
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker and the contract
        vm.deal(address(attacker), attackerFund);
        vm.deal(address(this), 1 ether);

        // attacker deposits depositAmount into c (as attacker address)
        vm.prank(address(attacker));
        attacker.depositToC{value: depositAmount}();

        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // Now attacker calls withdrawAll which in the buggy version will call out before zeroing
        // and re-enter to try to drain extra funds. We capture whether withdrawAll completed.
        bool ok;
        try attacker.callWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after withdrawAll completes (successfully or not),
        // the contract's balance decreased by exactly depositAmount when the call returned successfully.
        // We frame the assertion so that the correct contract always satisfies it for all inputs,
        // while the mutant (re-entrant vulnerable) will for some inputs leave a larger-than-expected
        // decrease (i.e., allow draining more than depositAmount), violating the rule.
        if (ok) {
            uint256 after = address(c).balance;
            // Expect exactly depositAmount was removed from contract balance
            assertTrue(before - after == depositAmount);
        } else {
            // If withdraw reverted, then the property (contract balance decreased by depositAmount)
            // does not hold; assert the known false to fail the test for this branch so that the
            // test only passes for the reference implementation which will not revert here.
            assertTrue(false);
        }
    }
}

// Minimal re-entrant attacker that re-enters on receive()
contract ReentrantAttacker {
    address public target;
    bool public reentered;

    constructor(address _target) payable {
        target = _target;
    }

    // deposit helper
    function depositToC() external payable {
        // deposit into C via its payable deposit()
        (bool ok, ) = target.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(ok);
    }

    // call withdrawAll on target
    function callWithdraw() external {
        // call withdrawAll as this contract
        (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        require(ok);
    }

    receive() external payable {
        // on receive, attempt a single re-entry if not already done
        if (!reentered) {
            reentered = true;
            // try to re-enter withdrawAll to exploit vulnerable order
            // ignore revert to allow outer call to continue
            (bool s, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
            // do nothing with s
        }
    }
}

