pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit and an address for the (potential) attacker
    function testFuzz_property(uint256 amt, address attacker) public {
        // keep amount in a reasonable range and non-zero
        amt = bound(amt, 1, 1 ether);
        // avoid the zero address for clarity
        vm.assume(attacker != address(0));

        // deploy an adversarial reentrant helper that will try to re-enter withdrawAll
        ReentrantAttacker a = new ReentrantAttacker(address(c));

        // fund the attacker externally so it can deposit
        vm.deal(address(a), amt);

        // attacker deposits into C (route through the attacker's fallback to call deposit)
        // deposit is public payable, so call it directly from attacker
        vm.prank(address(a));
        c.deposit{value: amt}();

        // Now attacker invokes withdrawAll; in the buggy contract the attacker can reenter
        // causing its recorded credit to remain non-zero after completion for some inputs.
        // We call withdrawAll from the attacker address so that msg.sender is the attacker.
        vm.prank(address(a));
        // call withdrawAll; it may succeed or revert depending on the contract variant
        try c.withdrawAll() {
            // after the call completes, read the public mapping via the auto getter
            // credit is a mapping(address => uint) with public visibility in the original description
            // but since we must observe c only via its public surface, we call the autogenerated getter credit(address)
            // If credit getter is not present in the real C_under_test, this will fail to compile — but per spec, credit has a getter.
            uint postCredit = c.credit(address(a));
            // The correct contract guarantees the depositor's credit is zero after withdrawAll for all inputs.
            // The mutant can leave it non-zero for some inputs (reentrancy). Assert the universal property here.
            assertTrue(postCredit == 0);
        } catch {
            // If withdrawAll reverts, still read the credit mapping (must be accessible) and assert it's zero.
            uint postCredit = c.credit(address(a));
            assertTrue(postCredit == 0);
        }
    }
}

// Minimal reentrant attacker: on receiving Ether it will try to call withdrawAll again once.
contract ReentrantAttacker {
    address target;
    bool reentered;
    constructor(address _t) {
        target = _t;
    }
    // deposit helper
    receive() external payable {}

    // Fallback to attempt reentrancy when receiving funds
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to re-enter withdrawAll
            (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
            // ignore success/failure; behavior differences are observed on c's state after external call
            ok;
        }
    }
}

